// Deterministic discrete-event sim: no Date.now(), no randomness.
const POOL = 24;            // pool_size
const QPS = 50;             // arrivals per second
const HOLD_MS = 30000;      // transaction hold time (Stripe inside BEGIN)
const WAIT_TIMEOUT = 10000; // query_wait_timeout
const WINDOW_MS = 2000;     // simulate 2 seconds of arrivals

const arrivalGap = 1000 / QPS;            // ms between arrivals
const freeAt = new Array(POOL).fill(0);   // time each backend becomes free
let served = 0, rejected = 0;

const nArrivals = Math.floor(WINDOW_MS / arrivalGap);
for (let i = 0; i < nArrivals; i++) {
  const t = i * arrivalGap;
  // pick the backend that frees up earliest
  let b = 0;
  for (let j = 1; j < POOL; j++) if (freeAt[j] < freeAt[b]) b = j;
  const wait = Math.max(0, freeAt[b] - t);
  if (wait > WAIT_TIMEOUT) {
    rejected++;
  } else {
    served++;
    freeAt[b] = Math.max(freeAt[b], t) + HOLD_MS;
  }
}
console.log('arrivals=' + nArrivals + ' served=' + served + ' rejected=' + rejected);
